def yt(name):
    return 'https://www.youtube.com/results?search_query=' + urllib.parse.quote(name + ' שיר חנוכה')


def write_rights_log():
    log = {'updated': '2026-11-23', 'rule': 'טקסט מלא רק לטקסט מסורתי או למחבר שנפטר עד 1955. אחרת: כותרת, יוצרים, פתיחה של עד 10 מילים וקישור.',
           'songs': [dict(name=s['name'], status=s['status'], who=s['who'], full_text=True) for s in FREE] +
                    [dict(name=s['name'], words=s['words'], music=s['music'], status='מוגן, בלי טקסט מלא', full_text=False, source='משרד החינוך, רשימת שירי חנוכה; מעריב, "הסיפורים מאחורי שירי החנוכה"') for s in PROT]}
    p = os.path.join(ROOT, 'tools', 'chanuka_plus', 'shirim_rights.json')
    json.dump(log, open(p, 'w', encoding='utf8'), ensure_ascii=False, indent=1)


